import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int h = sc.nextInt();
        int n = sc.nextInt();

        int l = 1;
        int r = (int) Math.pow(2, h);
        int res = 0;
        int dirFlag = 0;

        while (l < r) {
            int mid = (l + r) / 2;
            if (n <= mid) {
                if (dirFlag == 0) {
                    res += 1;
                    dirFlag = 1;
                } else {
                    res += (int) Math.pow(2, h);
                }
                r = mid;
            } else {
                if (dirFlag == 1) {
                    res += 1;
                    dirFlag = 0;
                } else {
                    res += (int) Math.pow(2, h);
                }
                l = mid + 1;
            }
            h -= 1;
        }

        System.out.println(res);
    }
}
